// Üretilen dosya: tool/ozgun/uret.py. Edebiyat · Türk edebiyatı: Tanzimat'tan Cumhuriyet'e yazarlar ve eserler (zor).
const ozLiterature2Zor = <(String, String, List<String>, String)>[
  ('Aşağıdakilerden hangisi Ahmet Vefik Paşa\'nın hazırladığı sözlüktür?', 'Lehçe-i Osmani', ['Kamus-ı Türki', 'Lügat-ı Naci', 'Kamusü\'l-a\'lam'], 'Lehçe-i Osmani, Ahmet Vefik Paşa\'nın Türkçe sözlüğüdür; Kamus-ı Türki ve Kamusü\'l-a\'lam Şemsettin Sami\'ye, Lügat-ı Naci Muallim Naci\'ye aittir.'),
  ('Ebüzziya Tevfik\'in Tanzimat edebiyatına yaptığı katkılardan biri olan Numune-i Edebiyat-ı Osmaniye nasıl bir eserdir?', 'Yeni edebiyat yazarlarından örnekler sunan bir seçki', ['Divan şairlerinin hayatlarını ve şiirlerinden örnekleri anlatan bir tezkire', 'Batı\'dan çevrilmiş bir roman', 'Ziya Paşa\'ya cevap olarak yazılmış bir manzume'], 'Numune-i Edebiyat-ı Osmaniye, Tanzimat yazarlarının düzyazılarından örnekler içeren ve okullarda da okutulan bir seçkidir.'),
  ('Şair Evlenmesi\'nde Müştak Bey\'in arkadaşı olan ve sorunun para yoluyla çözülmesini sağlayan kişi kimdir?', 'Hikmet Efendi', ['Batak Efendi', 'Keşfi Bey', 'Abdullah Çavuş'], 'Hikmet Efendi, mahalle imamı Batak Efendi\'ye para vererek Müştak Bey\'in sevdiği Kumru ile evlenmesini sağlar.'),
  ('Şinasi\'nin Reşit Paşa için yazdığı kasidelerde Divan geleneğinden ayrılan yön nedir?', 'Övgünün kişisel çıkar yerine Tanzimat\'ın getirdiği yenilik fikirleri üzerine kurulması', ['Kasidelerin hece ölçüsüyle ve dörtlüklerle yazılması', 'Kasidede nesip bölümünün iki kez tekrarlanması ve övgü bölümünün hiç yer almaması', 'Övülen kişinin adının hiç anılmaması'], 'Şinasi Reşit Paşa\'yı bir hükümdar gibi değil, akıl ve kanunla toplumu yenileyen bir devlet adamı olarak över; içerik yenidir, biçim eskidir.'),
  ('İntibah\'ta romantizmin etkisini gösteren özelliklerden biri hangisidir?', 'Doğa tasvirlerinin kahramanın duygularıyla birlikte verilmesi', ['Olayların bilimsel deney yöntemiyle açıklanması', 'Kahramanların davranışlarının kalıtım ve çevre yasalarıyla belirlenmesi', 'Anlatıcının hiçbir yorum yapmadan gözlemlemesi'], 'Çamlıca Bahçesi\'nin coşkulu tasviri ve Ali Bey\'in duygularının doğayla bütünleşmesi romantik etkidir; deney yöntemi ve kalıtım ise natüralizme aittir.'),
  ('Muallim Naci\'nin edebiyat terimlerini açıklamak amacıyla hazırladığı eser hangisidir?', 'Istılahat-ı Edebiye', ['Talim-i Edebiyat', 'Takdir-i Elhan', 'Hayat ve Kitaplar'], 'Istılahat-ı Edebiye, Muallim Naci\'nin edebiyat terimlerini tanıttığı eserdir; Talim-i Edebiyat ve Takdir-i Elhan Recaizade\'nin, Hayat ve Kitaplar Ahmet Şuayp\'ındır.'),
  ('Namık Kemal\'in Fransız düşünürü Ernest Renan\'ın İslamiyet aleyhindeki konferansına cevap olarak yazdığı eser hangisidir?', 'Renan Müdafaanamesi', ['Tahrib-i Harabat', 'İrfan Paşa\'ya Mektup', 'Mukaddime-i Celal'], 'Renan Müdafaanamesi, Renan\'ın İslam\'ın bilime engel olduğu iddiasına karşı yazılmış bir reddiyedir.'),
  ('Namık Kemal\'in Selahaddin Eyyubi, Fatih, Yavuz Sultan Selim ve Emir Nevruz biyografilerini bir araya getirdiği eser hangisidir?', 'Evrak-ı Perişan', ['Tahrib-i Harabat', 'Mukaddime-i Celal', 'Celâleddin Harzemşah'], 'Evrak-ı Perişan, tarihî kahramanların hayatlarını övgüyle anlatan bir biyografi kitabıdır.'),
  ('Namık Kemal\'in hayatının son yıllarında mutasarrıf olarak bulunduğu ve 1888\'de öldüğü ada hangisidir?', 'Sakız', ['Midilli', 'Rodos', 'Kıbrıs'], 'Namık Kemal Midilli ve Rodos\'taki görevlerinden sonra Sakız mutasarrıfı iken öldü; mezarı Bolayır\'dadır.'),
  ('Namık Kemal\'in mezarının bulunduğu Bolayır\'ın ona bir anlam ifade etmesinin nedeni nedir?', 'Mezarının Süleyman Paşa\'nın türbesi yanında, kendi isteğiyle buraya yapılması', ['Bolayır\'da doğup büyümüş olması', 'Bolayır\'da ilk gazetesini çıkarmış olması', 'Bolayır\'da uzun yıllar sürgün olarak yaşamış ve eserlerinin çoğunu orada yazmış olması'], 'Namık Kemal, Rumeli\'ye ilk geçen Osmanlı komutanı Süleyman Paşa\'nın yanına gömülmeyi vasiyet etmiştir.'),
  ('Ahmet Mithat\'ın Zola\'dan haberdar olarak yazdığı ve önsözünde gözleme dayalı "tabii" yöntemi denediğini söylediği roman hangisidir?', 'Müşahedat', ['Hasan Mellah', 'Dürdane Hanım', 'Jön Türk'], 'Ahmet Mithat, Müşahedat\'ta gözleme dayalı yazma yöntemini kendi anlayışıyla denediğini belirtir; ancak araya girip okura seslenme alışkanlığını bırakmaz.'),
  ('Şemsettin Sami\'nin altı ciltlik tarih ve coğrafya ağırlıklı ansiklopedisi hangisidir?', 'Kamusü\'l-a\'lam', ['Kamus-ı Türki', 'Durub-ı Emsal-i Osmaniye', 'Numune-i Edebiyat-ı Osmaniye'], 'Kamusü\'l-a\'lam özel adlar ansiklopedisidir; Kamus-ı Türki ise sözlüğüdür.'),
  ('Şemsettin Sami\'nin sadakat ve söz tutma temasını işlediği, Arnavut yaşayışından alınmış konusuyla dikkat çeken oyunu hangisidir?', 'Besa yahut Ahde Vefa', ['Gave', 'Seydi Yahya ve Kahraman Kızı', 'Vatan yahut Silistre'], '"Besa" Arnavutçada verilen söz demektir; oyun, verilen söze bağlılık uğruna katlanılan ağır fedakârlıkları işler.'),
  ('Araba Sevdası\'nda Bihruz Bey\'in hayal ile gerçek arasında yaşadığı çatışma, romanın hangi edebî akımlar arasındaki geçişini yansıttığını düşündürür?', 'Romantizmden realizme geçişi', ['Klasisizmden romantizme geçişi', 'Sembolizmden parnasizme geçişi', 'Natüralizmden empresyonizme geçişi'], 'Bihruz\'un romantik hayalleri gerçekçi bir bakışla alaya alınır; roman romantizmin eleştirisi üzerinden realizme yaklaşır.'),
  ('Recaizade Mahmut Ekrem ile Muallim Naci arasındaki kafiye tartışmasında Recaizade\'nin görüşü hangisidir?', 'Kafiyenin göz için olduğu, yazılışta benzeyen seslerin kafiye sayılabileceği', ['Kafiyenin yalnız kulak için olduğu, harflerin yazılışının hiçbir önem taşımadığı', 'Şiirde kafiyenin tamamen gereksiz olduğu', 'Kafiyenin yalnız redif ile sağlanabileceği'], 'Recaizade "kafiye göz içindir" der; Muallim Naci ise "kafiye kulak içindir" görüşüyle eski şiiri savunur.'),
  ('Recaizade Mahmut Ekrem\'in "Muhsin Bey yahut Şairliğin Hazin Bir Neticesi" adlı eseri hangi türdedir?', 'Uzun hikâye', ['Manzum tiyatro', 'Edebiyat kuramı kitabı', 'Gezi yazısı'], 'Muhsin Bey, Recaizade\'nin hikâye türündeki eserlerindendir; Şemsa da onun diğer hikâyesidir.'),
  ('Makber\'de ölüm karşısında duyulan acının yanında Allah\'a isyan ve sorgulamanın da yer alması hangi özelliği gösterir?', 'Şiire metafizik kaygı ve felsefi sorgulamanın girmesi', ['Şiirin tasavvufi teslimiyete ve vahdet anlayışına bağlanması', 'Şiirin yalnız tarihî olayları anlatması', 'Şiirin mizahi bir dille yazılması'], 'Hamit, ölüm karşısında inanç ile şüphe arasında bocalar; bu metafizik sorgulama Türk şiirinde yeni bir derinlik getirmiştir.'),
  ('Abdülhak Hamit\'in şiir dili ve tekniği için aşağıdakilerden hangisi söylenebilir?', 'Aruzu kullanırken ölçü ve uyak kurallarına zaman zaman uymayıp düzensizliğe düşmüştür.', ['Yalnız hece ölçüsüyle ve sade halk diliyle yazmıştır.', 'Ölçü ve uyağı bütünüyle bırakıp serbest şiir yazmıştır.', 'Sadece Divan nazım biçimlerinin ve aruzun kurallarına en küçük ayrıntısına kadar titizlikle bağlı kalmıştır.'], 'Hamit, düşünce ve duyguyu öne aldığı için şekle özen göstermemiş, dilde ve ölçüde düzensizliğe düşmüştür; bu, ona yöneltilen başlıca eleştiridir.'),
  ('Abdülhak Hamit\'in kişileri ve olayları İngiltere\'de geçen, ihtiraslı bir kadının tutkularını işleyen oyunu hangisidir?', 'Finten', ['Duhter-i Hindu', 'Macera-yı Aşk', 'Liberte'], 'Finten, Hamit\'in Londra\'daki görevi sırasında edindiği gözlemlerle yazılmış, İngiliz sosyetesinde geçen bir trajedidir.'),
  ('Sami Paşazade Sezai\'nin makalelerini topladığı eser hangisidir?', 'Rumuzü\'l-Edeb', ['Bize Göre', 'Evrak-ı Eyyam', 'Hayat ve Kitaplar'], 'Rumuzü\'l-Edeb, Sezai\'nin edebiyat ve fikir yazılarını içerir; diğerleri sırasıyla Ahmet Haşim, Cenap Şahabettin ve Ahmet Şuayp\'ındır.'),
  ('Nabizade Nazım\'ın Zola\'yı örnek alma isteğine karşın eserlerinde tam bir natüralist sayılamamasının nedeni hangisi olabilir?', 'Ahlaki kaygılarla bazı gerçekleri yumuşatması', ['Eserlerinde gözlem yapmamış olması', 'Yalnız şiir yazmış olması', 'Bütün eserlerini olağanüstü olaylarla dolu masal biçiminde kurması'], 'Nabizade gözleme önem verse de toplumun ahlak anlayışına aykırı düşmemek için sert gerçekleri olduğu gibi vermekten çekinmiştir.'),
  ('Muallim Naci\'nin Tercüman-ı Hakikat gazetesindeki edebiyat sayfasını yönetmesinin önemli bir sonucu nedir?', 'Etrafında eski şiire bağlı genç şairlerden oluşan bir çevre oluşturması', ['Servet-i Fünun dergisinin kurucusu olması', 'Hece ölçüsünü yaygınlaştırması', 'Batılı nazım biçimlerini ve serbest müstezadı ilk kez Türk şiirinde kullanması'], 'Naci, bu sayfada genç şairlerin ürünlerini yayımlayıp onları yönlendirdi; böylece "Naci ekolü" denilen gelenekçi bir çevre doğdu.'),
  ('Muallim Naci\'nin şiir kitapları arasında yer almayan eser hangisidir?', 'Pejmürde', ['Ateşpâre', 'Şerare', 'Füruzan ve Sünbüle'], 'Ateşpâre, Şerare ve Füruzan Naci\'nin şiir kitaplarıdır; Pejmürde ise Recaizade Mahmut Ekrem\'e aittir.'),
  ('Hüseyin Rahmi Gürpınar\'ın eserleri natüralizm bakımından değerlendirildiğinde hangi yargı en uygundur?', 'Natüralizmden etkilenmiş ama mizah ve öğreticilik nedeniyle akımın kurallarını tam uygulamamıştır.', ['Natüralizmin bütün kurallarını eksiksiz uygulayan ilk yazardır.', 'Natüralizme karşı çıkıp yalnız sembolist romanlar yazmış, gözleme dayalı anlatıyı ve gerçekçi tasviri reddetmiştir.', 'Natüralizmi hiç tanımadan yalnız masallar yazmıştır.'], 'Hüseyin Rahmi Zola\'dan etkilenmiştir; ancak araya girip öğüt vermesi ve güldürüye yönelmesi onu tam bir natüralist olmaktan uzaklaştırır.'),
  ('Tevfik Fikret\'in şiirlerinde "Promete" figürüne yer vermesi onun hangi düşüncesini simgeler?', 'Bilgiyi ve aydınlanmayı insanlığa getiren isyankâr insan idealini', ['Tasavvufi teslimiyet, kadere boyun eğme ve dünyadan el çekme isteğini', 'Eski Yunan tanrılarına inanç duymasını', 'Saray hayatına duyduğu özlemi'], 'Prometheus ateşi tanrılardan çalıp insanlığa veren mitolojik kahramandır; Fikret bu figürle akıl, bilim ve özgürlüğü yücelten tavrını simgeler.'),
  ('Tevfik Fikret\'in şiirleri bir öğretmen tarafından "bireysel şiirleri" ve "toplumsal şiirleri" olarak sınıflandırılırsa aşağıdakilerden hangisi "toplumsal" grupta yer alır?', 'Millet Şarkısı', ['Yağmur', 'Bir Lahza-i Teehhür', 'Nesrin'], 'Millet Şarkısı Meşrutiyet sonrasında millete seslenen toplumsal bir şiirdir. Yağmur, Bir Lahza-i Teehhür ve Nesrin ise doğa, aşk ve hayal üzerine kurulmuş bireysel şiirlerdir.'),
  ('Cenap Şahabettin\'in yazdığı tiyatro eserleri arasında yer alan eser hangisidir?', 'Yalan', ['Sahra', 'Zehra', 'Sis ve Han-ı Yağma'], 'Yalan ve Körebe, Cenap Şahabettin\'in tiyatro eserleridir; Sahra Abdülhak Hamit\'in, Zehra Nabizade Nazım\'ın, Sis ise Tevfik Fikret\'in eseridir.'),
  ('Halit Ziya Uşaklıgil\'in hangi şehirde yaşarken edebiyata başladığı, orada gazete ve dergi çıkardığı bilinir?', 'İzmir', ['Selanik', 'Bursa', 'Trabzon'], 'Halit Ziya gençlik yıllarını İzmir\'de geçirmiş; Nevruz dergisini ve Hizmet gazetesini burada çıkarmıştır.'),
  ('Halit Ziya\'nın Mabeyn başkâtipliği sırasındaki gözlemlerini anlattığı hatırat hangisidir?', 'Saray ve Ötesi', ['Kırk Yıl', 'Zoraki Diplomat', 'Politikada 45 Yıl'], 'Saray ve Ötesi, Halit Ziya\'nın Sultan Mehmet Reşat döneminde sarayda başkâtip olarak geçirdiği yılları anlatır.'),
  ('Aşağıdaki oyunlardan hangisi Mehmet Rauf\'a aittir?', 'Pençe', ['Körebe', 'Akif Bey', 'Vatan yahut Silistre'], 'Pençe (1909), Mehmet Rauf\'un oyunudur; Körebe Cenap Şahabettin\'in, Akif Bey ile Vatan yahut Silistre Namık Kemal\'indir.'),
  ('Hüseyin Cahit Yalçın\'ın Servet-i Fünun yıllarındaki hikâyelerini topladığı eserler hangi seçenekte birlikte verilmiştir?', 'Hayat-ı Muhayyel ve Hayat-ı Hakikiye Sahneleri', ['Küçük Şeyler ve Rumuzü\'l-Edeb', 'Letaif-i Rivayat ve Kıssadan Hisse', 'Memleket Hikâyeleri ve Gurbet Hikâyeleri'], 'Hayat-ı Muhayyel (1898) ve Hayat-ı Hakikiye Sahneleri (1899), Hüseyin Cahit\'in hikâye kitaplarıdır.'),
  ('Hüseyin Cahit Yalçın\'ın Servet-i Fünun topluluğunu ve dönemin edebî tartışmalarını anlattığı eseri hangisidir?', 'Edebî Hatıralar', ['Kırk Yıl', 'Gençlik ve Edebiyat Hatıraları', 'Saray ve Ötesi'], 'Edebî Hatıralar, Hüseyin Cahit\'in Servet-i Fünun çevresine dair önemli bir kaynak eseridir; Gençlik ve Edebiyat Hatıraları ise Yakup Kadri\'nindir.'),
  ('Süleyman Nazif için aşağıdakilerden hangisi doğrudur?', 'Servet-i Fünun çevresinde yer almış, coşkulu ve hitabet gücü yüksek düzyazısıyla tanınmıştır.', ['Fecr-i Âti\'nin beyannamesini kaleme almıştır.', 'Yeni Lisan makalesini yazarak Millî Edebiyat\'ı başlatmıştır.', 'Bütün eserlerini hece ölçüsüyle yazmış bir halk şairidir.'], 'Süleyman Nazif Servet-i Fünun\'a yakın durmuş; özellikle siyasi makaleleri ve hitabetli nesriyle tanınmıştır.'),
  ('Servet-i Fünun döneminin eleştirmenlerinden biri olan Ahmet Şuayp\'ın eleştiri yazılarını topladığı eser hangisidir?', 'Hayat ve Kitaplar', ['Takdir-i Elhan', 'Edebî Hatıralar', 'Bize Göre'], 'Hayat ve Kitaplar, Ahmet Şuayp\'ın Batılı yazarlar ve fikir akımları üzerine yazdığı eleştiri yazılarını içerir.'),
  ('Safvet Ziya\'nın Servet-i Fünun döneminde yazdığı ve İstanbul sosyetesini anlattığı romanı hangisidir?', 'Salon Köşelerinde', ['Kırık Hayatlar', 'Ferda-yı Garam', 'Nemide'], 'Salon Köşelerinde, Safvet Ziya\'nın Batılılaşmış bir konak çevresini anlattığı romanıdır.'),
  ('Mehmet Emin Yurdakul\'un şiirleri hangi yönüyle eleştirilmiştir?', 'Coşkulu hitaplara karşın sanat değerinin zaman zaman düşük, söyleyişin kuru kalması', ['Fazla ağır ve süslü bir dil kullanması', 'Bireysel aşk temalarına aşırı yer vermesi', 'Divan şiirini körü körüne taklit etmesi'], 'Mehmet Emin\'in şiirleri öğretici ve hitabetli olduğundan sanat değeri bakımından zayıf bulunmuştur; ancak dil ve ölçü alanında öncülüğü önemlidir.'),
  ('Fecr-i Âti topluluğunun Servet-i Fünun\'dan ayrıldığı bir nokta olarak aşağıdakilerden hangisi gösterilebilir?', 'Topluluk olarak bir beyanname yayımlayıp sanat anlayışını açıklaması', ['Romanda realizmi tamamen reddedip yalnız tarihî konulara yönelmesi', 'Yalnız hece ölçüsüyle yazması', 'Halit Ziya\'yı başkan seçmesi'], 'Fecr-i Âti, Türk edebiyatında bir beyanname ile ortaya çıkan ilk topluluktur; ilkelerini toplu biçimde ilan etmiştir.'),
  ('Ahmet Haşim\'in şiirlerinde ölçü konusunda tutumu nedir?', 'Aruzu kullanmış, kalıpları serbest müstezat anlayışıyla esnek biçimde uygulamıştır.', ['Yalnız hece ölçüsünü kullanmış, aruzu Divan\'a ait bir kalıp sayarak reddetmiştir.', 'Ölçü kullanmayıp serbest nazımla yazmıştır.', 'Yalnız Divan\'ın kaside biçimini kullanmıştır.'], 'Haşim aruzla yazmış, ancak dize uzunluklarını serbestçe düzenleyerek Servet-i Fünun\'dan gelen esnek biçimi sürdürmüştür.'),
  ('Ahmet Haşim\'in "Müslüman Saati" adlı yazısında ele aldığı karşıtlık nasıl özetlenebilir?', 'Doğu\'nun zaman anlayışı ile Batı\'nın zaman anlayışı arasındaki fark', ['Köy ile şehir arasındaki ekonomik fark', 'Hece ile aruz arasındaki ölçü farkı', 'Roman ile hikâye arasındaki biçim ve uzunluk farkının okura etkisi'], 'Haşim bu denemesinde ezan vakitlerine göre işleyen geleneksel zaman algısı ile Batı\'nın saat düzenini karşılaştırır.'),
  ('Yeni Lisan makalesindeki dil anlayışı için hangisi doğrudur?', 'Dilde tasfiyecilik yerine konuşma diline dayanan bir sadeleşmeyi savunur.', ['Türkçeye yerleşmiş bütün yabancı kelimelerin atılmasını ister.', 'Çağatay Türkçesinin yazı dili yapılmasını önerir.', 'Arapça kelimelerin yerine Fransızca kelimeler alınarak Batılılaşmanın hızlandırılmasını savunur.'], 'Genç Kalemler yazarları halkın kullandığı, Türkçeleşmiş kelimeleri korur; yalnız yabancı kuralları ve kullanılmayan kelimeleri dışarıda bırakır.'),
  ('Mehmet Akif\'in "Seyfi Baba", "Küfe", "Hasta" gibi şiirleri hangi yönüyle Tevfik Fikret\'in "Balıkçılar" şiiriyle benzerlik gösterir?', 'Yoksul halkın acılarını gerçekçi bir bakışla dile getirmeleri', ['Sembolist bir anlayışla yazılmaları', 'Saray hayatını ve paşaların ihtişamını övgüyle anlatmaları', 'Hece ölçüsüyle yazılmaları'], 'İki şair de farklı dünya görüşlerine sahip olsa da yoksulluğu ve halkın sıkıntılarını şiirlerine taşımıştır.'),
  ('İstiklal Marşı\'nın bugün okunan bestesinin bestecisi kimdir?', 'Osman Zeki Üngör', ['Cemal Reşit Rey', 'Itri', 'Ali Rıfat Çağatay'], 'Marşın ilk yıllarda Ali Rıfat Çağatay\'ın bestesi de kullanılmış; 1930\'dan itibaren Osman Zeki Üngör\'ün bestesi resmî olarak benimsenmiştir.'),
  ('Yahya Kemal\'in şiir anlayışı için en doğru yorum hangisidir?', 'Divan şiirinin ahengini ve konuşulan İstanbul Türkçesini birleştiren "yeni bir klasisizm"', ['Halk şiiri biçimlerini ve koşma, semai gibi türleri sürdüren bir halkçılık', 'Serbest nazma dayalı bir modernizm', 'Ölçüsüz ve uyaksız bir şiir anlayışı'], 'Yahya Kemal, gelenekle bağını koparmadan konuşma diline dayalı, biçimce kusursuz bir şiir kurmuştur.'),
  ('Sinekli Bakkal romanının ilk kez hangi dilde ve hangi adla yayımlandığı bilinir?', 'İngilizce, The Clown and His Daughter', ['Fransızca, Le Petit Épicier', 'Almanca, Die Tochter des Narren', 'Rusça, Doch Shuta'], 'Halide Edip romanı önce İngilizce yazıp 1935\'te yayımlamış, Türkçesi daha sonra çıkmıştır.'),
  ('Halide Edip\'in romanlarında gelişim çizgisi düşünüldüğünde aşağıdaki sıralamalardan hangisi doğrudur?', 'Bireysel ve psikolojik romanlar → Millî Mücadele romanları → Toplumsal ve töre romanları', ['Millî Mücadele romanları → Psikolojik romanlar → Tarihî romanlar', 'Köy romanları → Aşk romanları → Bilimkurgu romanları', 'Tarihî romanlar → Fantastik romanlar → Psikolojik romanlar'], 'Handan, Seviye Talip gibi ilk romanlarından sonra Ateşten Gömlek ve Vurun Kahpeye gelir; Sinekli Bakkal gibi toplumsal romanlar daha sonraki dönemindedir.'),
  ('Halide Edip\'in hayatını ve Millî Mücadele yıllarını anlattığı anı kitapları hangi seçenekte birlikte verilmiştir?', 'Mor Salkımlı Ev ve Türk\'ün Ateşle İmtihanı', ['Kırk Yıl ve Saray ve Ötesi', 'Edebî Hatıralar ve Kavgalarım', 'Zoraki Diplomat ve Anamın Kitabı'], 'Mor Salkımlı Ev çocukluk ve gençlik yıllarını, Türk\'ün Ateşle İmtihanı ise Millî Mücadele dönemini anlatır.'),
  ('Reşat Nuri\'nin tiyatro eserleri arasında yer alan oyun hangisidir?', 'Hülleci', ['Vatan yahut Silistre', 'Şair Evlenmesi', 'Finten'], 'Hülleci, Reşat Nuri\'nin oyunlarındandır; diğerleri sırasıyla Namık Kemal, Şinasi ve Abdülhak Hamit\'e aittir.'),
  ('Yakup Kadri\'nin Ankara romanı yapı bakımından nasıl bir özellik taşır?', 'Selma Hanım\'ın hayatı üzerinden Ankara\'yı üç ayrı dönemde anlatması', ['Bütünüyle iki kadın arasındaki mektuplardan oluşması', 'Olayların tek bir gün içinde geçmesi', 'Yalnız manzum bölümlerden oluşması'], 'Ankara (1934), Millî Mücadele, Cumhuriyet\'in ilk yılları ve geleceğe dair bir ütopya olmak üzere üç bölümden oluşur.'),
  ('Yakup Kadri\'nin Fecr-i Âti döneminde yazdığı, mensur şiir niteliği taşıyan ve tasavvufi bir hava içeren eserleri hangi seçenekte birlikte verilmiştir?', 'Erenlerin Bağından ve Okun Ucundan', ['Kiralık Konak ve Nur Baba', 'Yaban ve Ankara', 'Zoraki Diplomat ve Gençlik ve Edebiyat Hatıraları'], 'Erenlerin Bağından ve Okun Ucundan, Yakup Kadri\'nin mensur şiirlerini içerir.'),
  ('Yakup Kadri\'nin romanları bir bütün olarak değerlendirildiğinde en belirgin ortak yönü hangisidir?', 'Tanzimat\'tan Cumhuriyet\'e Türk toplumunun değişimini dönem dönem yansıtmaları', ['Romanlarının aynı aile çevresinde geçen bir dizi oluşturması', 'Hep bilimkurgu ve fantastik türde yazılmış olmaları', 'Toplumsal konulara yer vermeyip yalnız aşkı işlemeleri'], 'Kiralık Konak\'tan Panorama\'ya Yakup Kadri\'nin romanları, Türk toplumunun farklı dönemlerdeki dönüşümünü bir dizi hâlinde belgeler.'),
  ('Orhan Seyfi Orhon\'un masalsı bir aşk hikâyesini manzum biçimde anlattığı eseri hangisidir?', 'Peri Kızı ile Çoban Hikâyesi', ['Han Duvarları', 'Akından Akına', 'Fırtına ve Kar'], 'Peri Kızı ile Çoban Hikâyesi (1919), Orhan Seyfi\'nin hece ölçüsüyle yazdığı manzum bir hikâyedir.'),
  ('Halit Fahri Ozansoy\'un Beş Hececiler ile ilişkisi için hangisi doğrudur?', 'Beş Hececiler arasında yer almış, şiirin yanında tiyatro eserleri de yazmıştır.', ['Fecr-i Âti beyannamesinin tek yazarıdır.', 'Yeni Lisan makalesini kaleme almıştır.', 'Servet-i Fünun dergisinin kurucusudur.'], 'Halit Fahri, Beş Hececiler\'den biridir; şiirin yanında oyun yazarlığıyla da tanınır.'),
  ('Rıza Tevfik Bölükbaşı\'nın hece ölçüsüyle ve halk şiiri söyleyişine yakın bir dille yazdığı şiirlerini topladığı eser hangisidir?', 'Serab-ı Ömrüm', ['Göl Saatleri', 'Türkçe Şiirler', 'Han Duvarları'], 'Serab-ı Ömrüm, Rıza Tevfik\'in tasavvufi ve lirik şiirlerini içerir; "Filozof Rıza" diye de anılır.'),
  ('Aka Gündüz\'ün Millî Mücadele yıllarında Ankara\'da geçen ve geniş okur kitlesine ulaşan romanı hangisidir?', 'Dikmen Yıldızı', ['Ateşten Gömlek', 'Vurun Kahpeye', 'Yaban'], 'Dikmen Yıldızı (1928), Millî Mücadele\'yi Ankara çevresinde geçen bir aşk hikâyesiyle birlikte anlatır.'),
  ('Aşağıdaki romanların yayımlanış sırası hangi seçenekte eskiden yeniye doğru doğru verilmiştir?', 'Taaşşuk-ı Talat ve Fitnat → İntibah → Sergüzeşt → Mai ve Siyah', ['İntibah → Taaşşuk-ı Talat ve Fitnat → Mai ve Siyah → Sergüzeşt', 'Mai ve Siyah → Sergüzeşt → İntibah → Taaşşuk-ı Talat ve Fitnat', 'Sergüzeşt → İntibah → Mai ve Siyah → Taaşşuk-ı Talat ve Fitnat'], 'Taaşşuk-ı Talat ve Fitnat 1872, İntibah 1876, Sergüzeşt 1889, Mai ve Siyah 1897 yılında yayımlanmıştır.'),
  ('Aşağıdaki gazetelerin yayın hayatına başlama sırası hangisinde doğru verilmiştir?', 'Takvim-i Vekayi → Ceride-i Havadis → Tercüman-ı Ahval → Tasvir-i Efkâr', ['Tercüman-ı Ahval → Takvim-i Vekayi → Tasvir-i Efkâr → Ceride-i Havadis', 'Ceride-i Havadis → Tasvir-i Efkâr → Takvim-i Vekayi → Tercüman-ı Ahval', 'Tasvir-i Efkâr → Tercüman-ı Ahval → Ceride-i Havadis → Takvim-i Vekayi'], 'Takvim-i Vekayi 1831, Ceride-i Havadis 1840, Tercüman-ı Ahval 1860, Tasvir-i Efkâr 1862 yılında çıkmıştır.'),
  ('Ahmet Vefik Paşa\'nın Ebulgazi Bahadır Han\'dan Türkçeye aktardığı tarih eseri hangisidir?', 'Şecere-i Türki', ['Kamusü\'l-a\'lam', 'Evrak-ı Perişan', 'Tarih-i Cevdet'], 'Şecere-i Türk, Ebulgazi Bahadır Han\'ın Çağatayca yazdığı Türk tarihidir; Ahmet Vefik Paşa onu Osmanlı Türkçesine aktarmıştır.'),
  ('Ali Suavi\'nin 1867\'de çıkardığı ve Yeni Osmanlılar\'ın sesini duyuran gazete hangisidir?', 'Muhbir', ['İbret', 'Diyojen', 'Hadika'], 'Muhbir, Ali Suavi\'nin çıkardığı ve sert yazıları yüzünden kapatılan gazetedir; Ali Suavi daha sonra Avrupa\'ya kaçmıştır.'),
  ('Ebüzziya Tevfik\'in yayıncılık alanındaki önemli katkısı aşağıdakilerden hangisidir?', 'Kendi matbaasında yayımladığı küçük boyutlu kitap dizisiyle okumayı yaygınlaştırması', ['Osmanlı\'nın ilk matbaasını kurup Arap harfli kitap basımını başlatması', 'İlk resmî gazeteyi çıkarması', 'Servet-i Fünun dergisini kurması'], 'Ebüzziya Tevfik, Kütüphane-i Ebüzziya adıyla bilinen dizisiyle klasik ve yeni eserleri ucuz ve özenli baskılarla okura sunmuştur.'),
  ('Emin Nihat\'ın Müsameretname adlı eserinin Türk anlatı geleneğindeki yeri için en doğru yargı hangisidir?', 'Halk hikâyesinden modern hikâyeye geçişte yer alan bir örnek olması', ['Türk edebiyatının ilk psikolojik romanı olup bireyin iç dünyasını incelemesi', 'Batılı anlamda ilk tiyatro eseri olması', 'Servet-i Fünun\'un ilk hikâye kitabı olması'], 'Müsameretname, geleneksel anlatı unsurlarını taşıyan ama yeni bir anlatı biçimine yönelen, geçiş niteliğinde hikâyelerden oluşur.'),
  ('Abdülhak Hamit\'in tiyatrolarında Shakespeare etkisinin görülmesi aşağıdakilerden hangisiyle en iyi açıklanır?', 'Tarihî konuları güçlü tutkular ve trajik sonlarla işlemesi', ['Oyunlarında ortaoyunu kalıplarını kullanması', 'Oyunlarını tek perdelik, mutlu sonla biten töre komedileri olarak yazması', 'Oyunlarında yalnız günlük konuşma dilini kullanması'], 'Hamit\'in oyunlarında ihtiras, intikam, iktidar gibi tutkular ve trajik sonlar baskındır; bu yönüyle Shakespeare\'den etkilenmiştir.'),
  ('Recaizade Mahmut Ekrem\'in şiir anlayışını yansıtan "Güzel olan her şey şiirin konusudur" görüşü, Divan şiirinin hangi yaklaşımına karşı çıkar?', 'Şiire girecek konuların ve mazmunların belli kalıplarla sınırlandırılmasına', ['Şiirde aruz ölçüsünün kullanılmasına', 'Şiirin bir bütün olarak düşünülmesine', 'Şiirde Türkçe kelimelerin ve halk deyişlerinin kullanılmasına izin verilmesine'], 'Divan şiirinde konu ve imgeler büyük ölçüde belirlenmiş kalıplara dayanır; Recaizade şiirin konu alanını genişletmeyi savunur.'),
  ('Halit Ziya\'nın hikâyeciliği için aşağıdakilerden hangisi söylenebilir?', 'İstanbul\'un yanında İzmir ve çevresini de mekân olarak kullanmış, gözleme dayalı gerçekçi hikâyeler yazmıştır.', ['Yalnız tarihî ve destansı hikâyeler yazmış, konularını akıncılardan ve fetihlerden almıştır.', 'Hikâyelerini manzum olarak kaleme almıştır.', 'Hikâyelerinde yalnız Anadolu köylerini işlemiştir.'], 'Halit Ziya\'nın Bir Yazın Tarihi, Solgun Demet gibi hikâye kitaplarında İstanbul ve İzmir çevresinden insanlar gerçekçi bir bakışla anlatılır.'),
  ('Halit Ziya\'nın romanlarında kullandığı dil için en uygun yargı hangisidir?', 'Servet-i Fünun\'a özgü ağır bir dil kullanmış, sonraki baskılarda eserlerini sadeleştirmiştir.', ['Baştan sona öz Türkçe kelimelerle yazmıştır.', 'Halk ağzını ve yöresel söyleyişleri temel almıştır.', 'Romanlarını Fransızca yazıp Türkçeye çevirtmiş, bu yüzden dili yer yer çeviri kokan bir yazar olmuştur.'], 'Halit Ziya, Cumhuriyet döneminde romanlarını yeni okurlar için sadeleştirerek yeniden yayımlamıştır.'),
  ('Aşk-ı Memnu\'da Bihter\'in hayatına son vermesine yol açan gelişme hangisidir?', 'Yasak ilişkisinin ortaya çıkması ve Behlül\'ün kendisini terk etmesi', ['Adnan Bey\'in iflas etmesi', 'Annesi Firdevs Hanım\'ın ölmesi', 'Yalıda çıkan büyük yangında her şeyini ve ailesini kaybetmesi'], 'Behlül\'ün Nihal ile evlenmeye yönelmesi ve ilişkinin açığa çıkması Bihter\'i çaresiz bırakır; Bihter intihar eder.'),
  ('Tevfik Fikret\'in dinî konulardaki görüşleri nedeniyle Mehmet Akif ile aralarında bir karşıtlık doğmasına yol açan şiiri hangisidir?', 'Tarih-i Kadim', ['Balıkçılar', 'Ferda', 'Haluk\'un Defteri'], 'Fikret\'in Tarih-i Kadim şiirindeki dinî eleştiriler, Mehmet Akif\'in Safahat\'ta Fikret\'e yönelik sert eleştirilerine konu olmuştur.'),
  ('Tevfik Fikret\'in şiirde resim sanatıyla ilişki kurması ve tablo gibi tasvirler yapması hangi akımın etkisini gösterir?', 'Parnasizm', ['Sürrealizm', 'Fütürizm', 'Dadaizm'], 'Biçim kusursuzluğuna ve nesnel, resim gibi tasvire önem veren parnasizm, Fikret\'in şiirinde belirgindir; Fikret aynı zamanda resimle de ilgilenmiştir.'),
  ('Cenap Şahabettin\'in Servet-i Fünun dağıldıktan sonraki yıllarda yeni kuşakla ilişkisi için hangisi doğrudur?', 'Millî Edebiyat\'ın dil anlayışına karşı çıkıp yeni kuşakla tartışmalara girmiştir.', ['Millî Edebiyat\'ın kurucusu olmuş ve Genç Kalemler dergisinde Yeni Lisan makalesini yazarak sade dili savunmuştur.', 'Yeni Lisan makalesini yazmıştır.', 'Hece ölçüsünün en büyük savunucusu olmuştur.'], 'Cenap, sade dil ve hece akımına mesafeli durmuş, Millî Edebiyat yazarlarıyla dil konusunda tartışmalara girmiştir.'),
  ('Servet-i Fünun sanatçılarının yeni kelime ve tamlama türetme eğilimini en iyi gösteren örnek hangisidir?', '"Hande-i mehtab" gibi olağan dışı tamlamalar kurmaları', ['Halk deyişlerini aynen kullanmaları', 'Türkçe ekleri tamamen bırakmaları', 'Yalnız Fransızca kelimelerle yazıp Türkçe ekleri kullanmamaları'], 'Servet-i Fünuncular, soyut ile somutu birleştiren "hande-i mehtab" (ay ışığının gülüşü) gibi yeni, alışılmadık tamlamalar kurmuşlardır.'),
  ('Halit Ziya\'nın "Hikâye" adlı eserinin önemi nedir?', 'Roman ve hikâye türleri üzerine Türkçe yazılmış ilk kuramsal çalışmalardan olması', ['Bir şiir antolojisi olması', 'Türk edebiyatındaki ilk hikâye kitabı olması ve Batılı hikâyeyi başlatması', 'Bir gezi yazısı olması'], 'Halit Ziya, "Hikâye" adlı eserinde roman ve hikâye tekniğine dair görüşlerini açıklamış; bu, alanındaki öncü kuramsal çalışmalardandır.'),
  ('Mehmet Akif\'in Mısır\'a gitmesinin ardından burada üstlendiği önemli çalışma hangisidir?', 'Kur\'an-ı Kerim\'in Türkçe mealini hazırlamak', ['Arapça bir roman yazmak', 'Mısır\'da yeni bir gazete çıkarıp Millî Mücadele\'yi desteklemek', 'Türk Ocakları\'nı yönetmek'], 'Akif\'e Cumhuriyet\'in ilk yıllarında Kur\'an meali hazırlama görevi verilmişti; Mısır\'da bu çalışmayı sürdürmüş, ancak yayımlanmasını istememiştir.'),
  ('Mehmet Akif ile Tevfik Fikret karşılaştırıldığında aşağıdakilerden hangisi ikisinin ortak özelliğidir?', 'Toplumsal sorunlara duyarlı şiirler yazmaları ve aruzu ustalıkla kullanmaları', ['Hece ölçüsüyle yazmaları', 'Aynı dünya görüşünü paylaşmaları ve birbirlerini desteklemeleri', 'Fecr-i Âti\'de yer almaları'], 'İki şairin dünya görüşleri farklıdır; ancak ikisi de toplumcu şiirler yazmış ve aruzu başarıyla kullanmıştır.'),
  ('Yakup Kadri\'nin Yaban romanında köylülerin Millî Mücadele\'ye bakışı, Ahmet Celal\'in gözünden nasıl verilir?', 'Savaşa ve millî davaya ilgisiz, kendi dertlerine kapanmış olarak', ['Millî Mücadele\'nin coşkulu önderleri ve gönüllüleri olarak', 'Şehirli aydınları örnek alan, okumaya meraklı kişiler olarak', 'Ahmet Celal\'i kendilerinden sayıp ona her konuda danışan kişiler olarak'], 'Ahmet Celal, köylünün millî davaya uzak durduğunu, kendisini ise yabancı gördüğünü acıyla gözlemler; roman aydın ile halk arasındaki kopukluğu işler.'),
  ('Servet-i Fünun romanında olayların İstanbul\'un dar ve seçkin çevrelerinde geçmesi ile Millî Edebiyat romanında Anadolu\'nun öne çıkması karşılaştırıldığında hangi sonuca ulaşılır?', 'Romanın mekânı, sanatçıların toplumla kurdukları ilişkiye göre genişlemiştir.', ['Millî Edebiyat romanı yalnız İstanbul\'u anlatmıştır.', 'İki dönemde de romanın mekânı hiç değişmemiş, hep İstanbul yalıları olmuştur.', 'Servet-i Fünun romanı yalnız köyleri anlatmıştır.'], 'Bireyci Servet-i Fünun\'un dar mekânından, halka yönelen Millî Edebiyat\'ın Anadolu\'yu kucaklayan mekânına geçilmiştir.'),
  ('Tanzimat\'tan Millî Edebiyat\'a uzanan süreçte yazı dilinin değişimini en doğru özetleyen ifade hangisidir?', 'Tanzimat\'ta başlayan sadeleşme Servet-i Fünun\'da kesintiye uğramış, Millî Edebiyat\'ta güçlenerek sürmüştür.', ['Dil sürekli ağırlaşmış ve en ağır hâline Millî Edebiyat döneminde, Yeni Lisan\'la birlikte ulaşmıştır.', 'Dil Tanzimat\'ta en sade hâlindeydi ve sonra hiç değişmedi.', 'Dil yalnız Servet-i Fünun\'da sadeleşmiştir.'], 'Şinasi ve Namık Kemal sadeleşmeyi savunmuş, Servet-i Fünun ağır bir dile dönmüş, Yeni Lisan ile sade dil yeniden ilke hâline gelmiştir.'),
  ('Servet-i Fünun\'un bir romancısı ile Millî Edebiyat\'ın bir romancısının eserlerini karşılaştıran bir öğrenci, ikisinin ortak yönü olarak aşağıdakilerden hangisini bulur?', 'Batılı roman tekniğini başarıyla uygulamaları', ['Aynı mekânları anlatmaları', 'Aynı ağır, Arapça ve Farsça tamlamalarla dolu dili kullanmaları', 'Tesadüflere dayalı olay örgüsü kurmaları'], 'Halit Ziya ve Reşat Nuri gibi yazarlar farklı konu ve dil anlayışına sahip olsa da Batılı roman tekniğini ustalıkla kullanmışlardır.'),
  ('Ahmet Mithat Efendi\'nin tiyatro alanındaki eserleri arasında yer alan oyun hangisidir?', 'Çengi', ['Zor Nikâh', 'Besa', 'Şîr'], 'Çengi, Ahmet Mithat\'ın oyunlarındandır; Zor Nikâh Ahmet Vefik Paşa\'nın uyarlaması, Besa Şemsettin Sami\'nin, Şîr Sezai\'nin eseridir.'),
  ('Yakup Kadri\'nin Panorama romanının kapsadığı dönem için hangisi doğrudur?', 'Cumhuriyet\'in kuruluşundan 1950\'lere uzanan toplumsal değişmeyi geniş bir çerçevede anlatır.', ['Yalnız Tanzimat dönemini ve bu dönemde yetişen devlet adamlarını anlatır.', 'Yalnız Balkan Savaşları\'nı anlatır.', 'Osmanlı\'nın kuruluş yıllarını anlatır.'], 'Panorama, Cumhuriyet\'in kurulmasından sonraki yıllarda Türk toplumundaki değişimi geniş bir kadroyla işler.'),
  ('Refik Halit Karay\'ın sürgünden dönüşünden sonra Cumhuriyet döneminde yazdığı romanlar arasında yer alan eser hangisidir?', 'Nilgün', ['Memleket Hikâyeleri', 'Kirpinin Dedikleri', 'Gurbet Hikâyeleri'], 'Nilgün, Refik Halit\'in Cumhuriyet döneminde yazdığı romanlardandır; diğerleri hikâye ve mizah yazılarıdır.'),
  ('Refik Halit\'in Memleket Hikâyeleri\'nde Anadolu\'yu anlatış biçimi, Halide Edip ve Reşat Nuri\'nin bazı eserlerindeki idealize edilmiş Anadolu\'dan nasıl ayrılır?', 'Anadolu\'nun yoksulluğunu ve insanlarının zaaflarını süslemeden göstermesiyle', ['Anadolu\'yu hiç görmeden yazmasıyla', 'Anadolu\'yu bir masal ülkesi gibi, olağanüstü olaylar ve yaratıklarla anlatmasıyla', 'Anadolu\'yu yalnız tarihî zaferlerle anlatmasıyla'], 'Refik Halit, Anadolu\'yu gerçekçi ve yer yer alaycı bir gözle anlatır; bu, onu idealizmden ayırır.'),
  ('Mehmet Fuat Köprülü\'nün Türk edebiyat tarihçiliğine en önemli katkılarından biri olan 1918 tarihli eseri hangisidir?', 'Türk Edebiyatında İlk Mutasavvıflar', ['Türkçülüğün Esasları ve Türk Töresi', 'Hayat ve Kitaplar', 'Talim-i Edebiyat'], 'Fecr-i Âti\'de başlayan Köprülü, bu eserle Türk edebiyat tarihine bilimsel yöntemle yaklaşmanın öncüsü olmuştur.'),
  ('Hamdullah Suphi Tanrıöver\'in Millî Edebiyat ve Türkçülük hareketindeki rolü için hangisi doğrudur?', 'Türk Ocakları\'nın başkanlığını yapmış, hitabetli yazı ve konuşmalarıyla tanınmıştır.', ['Genç Kalemler\'i kurmuştur.', 'Şair Evlenmesi\'ni yazmıştır.', 'Servet-i Fünun dergisini kurup yazı işlerini Tevfik Fikret\'e bırakmıştır.'], 'Hamdullah Suphi, Türk Ocakları\'nın başkanıdır; ayrıca Akif\'i İstiklal Marşı yarışmasına katılmaya ikna eden kişidir.'),
  ('Millî Edebiyat döneminde Ömer Seyfettin ile Ali Canip\'in "Yeni Lisan" hareketini Selanik\'ten başlatmasının önemli bir sonucu nedir?', 'Dil meselesinin bir topluluk programı hâline gelmesi', ['Divan şiirinin yeniden canlanması', 'Servet-i Fünun topluluğunun yeniden kurulup dergiyi çıkarması', 'Aruzun tek ölçü olarak kabul edilmesi'], 'Yeni Lisan ile dilde sadeleşme bir kişisel tercih olmaktan çıkıp örgütlü bir edebî programa dönüşmüştür.'),
  ('Bir öğrenci "Türk hikâyeciliğinde Maupassant tarzının Ömer Seyfettin\'le, Anadolu gerçekçiliğinin Refik Halit\'le güçlendiğini" yazmıştır. Bu yargıyı destekleyen eser çifti hangisidir?', 'Kaşağı ve Memleket Hikâyeleri', ['Küçük Şeyler ve Letaif-i Rivayat', 'Mai ve Siyah ve Eylül', 'Safahat ve Göl Saatleri'], 'Kaşağı olay hikâyesinin, Memleket Hikâyeleri ise Anadolu\'yu gerçekçi biçimde anlatan hikâyeciliğin örneğidir.'),
  ('Abdülhak Hamit\'in Makber\'i Batılı bir duyarlılıkla yazılmış bir mersiye olarak değerlendirilirse, bunu destekleyen özellik hangisidir?', 'Kişisel acının bütün çıplaklığıyla ve felsefi sorgulamalarla anlatılması', ['Şiirin yalnız kalıplaşmış mazmunlarla kurulması', 'Ölen kişinin bir hükümdar olması ve ona övgüler dizilmesi', 'Şiirin bir zaferi kutlaması'], 'Divan mersiyeleri çoğu zaman kalıplara bağlıyken Makber, şairin kendi acısını bireysel ve sorgulayıcı bir dille anlatır.'),
  ('Millî Edebiyat döneminde hece ölçüsünü savunanların aruzun Türkçeye uymadığını söylerken dayandıkları temel gerekçe hangisidir?', 'Türkçede uzun ünlülerin bulunmaması ve aruzun kelimeleri zorlaması', ['Aruzun Fransız şiirinden alınmış olması', 'Aruzla yalnız mizahi şiir yazılabilmesi', 'Aruzun halk şiirinin tek ölçüsü olması'], 'Aruz uzun ve kısa hecelere dayanır; Türkçede doğal uzun ünlü bulunmadığı için kelimeleri ölçüye uydurmak zorlama gerektirir. Hececiler bu gerekçeyle heceyi "millî vezin" saydı.'),
  ('Abdülhak Hamit\'in Hindistan\'da İngiliz sömürge yönetimini ve bir Hint kızının dramını işlediği oyunu hangisidir?', 'Duhter-i Hindu', ['Eşber', 'Tezer', 'Sardanapal'], 'Duhter-i Hindu "Hint kızı" demektir; Hamit\'in Bombay\'daki görevi sırasındaki gözlemlerinden beslenir.'),
  ('Abdülhak Hamit\'in Endülüs Emevîlerinden III. Abdurrahman döneminde geçen oyunu hangisidir?', 'Tezer', ['Tarık yahut Endülüs Fethi', 'Finten', 'İlhan'], 'Tezer, Endülüs\'te geçen ve Abdurrahman III dönemindeki saray çatışmalarını işleyen tarihî bir oyundur.'),
  ('Şinasi ile Namık Kemal\'in gazetecilik anlayışları karşılaştırıldığında Namık Kemal\'in ayırıcı yönü hangisidir?', 'Yazılarında daha coşkulu ve siyasi bir mücadele dili kullanması', ['Hiç makale yazmaması', 'Gazeteyi yalnız resmî ilanlar için kullanması', 'Gazetede yalnız şiir yayımlaması'], 'Şinasi ölçülü ve öğretici bir dil kullanırken Namık Kemal, vatan ve hürriyet uğruna heyecanlı ve siyasi bir üslupla yazmıştır.'),
  ('Ziya Paşa\'nın "Şiir ve İnşa" makalesindeki düşünceleri dikkate alındığında, makale Millî Edebiyat\'ın hangi ilkesinin erken bir habercisi sayılabilir?', 'Halk edebiyatını millî edebiyatın kaynağı olarak görme', ['Sanatı sanat için yapma', 'Sembolist şiir anlayışı', 'Ağır ve süslü dil kullanma'], 'Ziya Paşa\'nın halk şiirini "asıl millî şiir" sayması, Millî Edebiyat\'ın halk kaynaklarına yönelişini önceden haber verir.'),
  ('Ahmet Haşim ile Yahya Kemal\'in şiirleri karşılaştırıldığında aşağıdakilerden hangisi ikisinin farklılığını en iyi gösterir?', 'Haşim kendi iç dünyasına kapanırken Yahya Kemal tarihe ve millî kimliğe yönelir.', ['Haşim aruz, Yahya Kemal serbest ölçü kullanır.', 'Haşim Tanzimat, Yahya Kemal Servet-i Fünun şairidir.', 'İkisi de yalnız hece ölçüsüyle yazar.'], 'İki şair de aruzla yazmıştır; Haşim\'in şiiri bireysel ve sembolik, Yahya Kemal\'inki ise tarih ve İstanbul merkezlidir.'),
  ('Nabizade Nazım\'ın Karabibik\'te konuşmalarda yöresel ağız özelliklerine yer vermesi hangi anlayışın ürünüdür?', 'Gerçekçi anlatım ve yerel renk verme isteği', ['Romantik bir masal havası yaratma ve okuru eğlendirme isteği', 'Divan şiirine öykünme', 'Okuru eğlendirmek için dili bozma'], 'Nabizade, köylülerin konuşmalarını Antalya ağzıyla vererek anlatıya gerçekçilik ve yerel renk kazandırmıştır.'),
  ('Yahya Kemal\'in Dergâh dergisi çevresindeki gençlere etkisi için en doğru yargı hangisidir?', 'Onları tarih ve gelenek bilinciyle yeni bir şiir arayışına yönlendirmiştir.', ['Onlara hece ölçüsünü öğretip Beş Hececiler topluluğunu kurmalarını sağlayarak yön vermiştir.', 'Onları Servet-i Fünun\'un dil anlayışına döndürmüştür.', 'Onları Fransız sürrealizmine yöneltmiştir.'], 'Yahya Kemal, Tanpınar gibi gençlere tarih, kültür ve gelenekle bağ kuran bir sanat anlayışı aşılamıştır.'),
  ('Türk edebiyatında Tanzimat\'tan Millî Edebiyat\'a uzanan dönemde aşağıdaki türlerden hangisi ilk kez Millî Edebiyat yıllarında belirgin bir gelişme göstermiştir?', 'Röportaj ve mülakat', ['Roman ve uzun hikâye', 'Tiyatro', 'Makale'], 'Roman, tiyatro ve makale Tanzimat\'ta başlamıştır; Ruşen Eşref\'in söyleşileriyle röportaj türü Millî Edebiyat yıllarında belirginleşmiştir.'),
  ('Tanzimat edebiyatında "hürriyet" kavramının işlenişi ile Millî Edebiyat\'ta "millet" kavramının işlenişi arasında nasıl bir ilişki kurulabilir?', 'Her ikisi de edebiyatı toplumu dönüştürmenin aracı olarak gören bir anlayışın ürünüdür.', ['İkisi de sanat için sanat anlayışının sonucudur ve toplumu dışarıda bırakan bir bireyciliği yansıtır.', 'İkisi de Divan şiirinin geleneksel temalarıdır.', 'İkisi de yalnız aşk şiirlerinde işlenmiştir.'], 'Namık Kemal\'in hürriyet şiirleri ile Gökalp\'in millet ülküsü, edebiyatı toplumsal bir görevle ilişkilendiren ortak bir çizgide buluşur.'),
  ('Bir araştırmacı Servet-i Fünun ile Millî Edebiyat arasında geçiş gösteren ve önce ağır dille başlayıp sonra Türkçü bir çizgiye geçen bir hikâyeciyi incelemek istiyor. Hangi yazar en uygundur?', 'Ahmet Hikmet Müftüoğlu', ['Halit Ziya Uşaklıgil', 'Hüseyin Cahit Yalçın', 'Cenap Şahabettin'], 'Ahmet Hikmet, Haristan ve Gülistan\'dan Çağlayanlar\'a uzanan çizgisiyle Servet-i Fünun\'dan Millî Edebiyat\'a geçişi temsil eder.'),
];
